sentaku Token { Number(int64); Plus; Times; Word(string); }
waza describe(t: Token) -> string {
    awase (t) {
        baai Number(n) { moshi (n > 9) { kaesu "big number"; } kaesu "number"; }
        baai Plus { kaesu "plus"; }
        baai Times { kaesu "times"; }
        baai Word(w) { kaesu w; }
    }
    kaesu "?";
}
kaku tokens = [Token.Number(3), Token.Plus(), Token.Number(42), Token.Times(), Token.Word("ことば")];
kaku i = 0; aida (i < len(tokens)) { chant(describe(tokens[i])); i = i + 1; }

waza make_counter(step: int64) -> () -> int64 {
    kaku n = 0;
    kaesu waza () -> int64 { n = n + step; kaesu n; };
}
waza compose(f: (int64) -> int64, g: (int64) -> int64) -> (int64) -> int64 {
    kaesu waza (x: int64) -> int64 { kaesu f(g(x)); };
}
waza each(xs: []int64, f: (int64) -> unit) -> unit { kaku i = 0; aida (i < len(xs)) { f(xs[i]); i = i + 1; } }
kaku c = make_counter(5); chant(c()); chant(c()); kaku d = make_counter(1); chant(d()); chant(c());
kaku inc = waza (x: int64) -> int64 { kaesu x + 1; };
kaku dbl = waza (x: int64) -> int64 { kaesu x * 2; };
chant(compose(inc, dbl)(10)); chant(compose(dbl, inc)(10));
kaku total = 0; each([1, 2, 3, 4], waza (x: int64) -> unit { total = total + x; }); chant(total);

kaku stock = Map[string, int64]();
stock["りんご"] = 3; stock["mochi"] = 12; stock["りんご"] = 4;
kaku apples = stock["りんご"]; moshi (apples != mu) { chant(apples); }
kaku m = stock["mochi"]; moshi (m != mu) { chant(m); }
chant(stock["missing"] == mu);
kaku squares = Map[int64, int64]();
kaku i = 0; aida (i < 100) { squares[i] = i * i; i = i + 1; }
kaku s = squares[99]; moshi (s != mu) { chant(s); }

kata Tree { value: int64; left: Tree?; right: Tree?; }
waza sum(t: Tree?) -> int64 { moshi (t == mu) { kaesu 0; } kaesu t.value + sum(t.left) + sum(t.right); }
waza find(xs: []int64, target: int64) -> int64? {
    kaku i = 0; aida (i < len(xs)) { moshi (xs[i] == target) { kaesu i; } i = i + 1; }
    kaesu mu;
}
kaku t = Tree { value: 1, left: Tree { value: 2, left: mu, right: mu }, right: Tree { value: 3, left: mu, right: mu } };
chant(sum(t)); chant(sum(mu));
kaku at = find([5, 6, 7], 7); moshi (at != mu) { chant(at); }
chant(find([5, 6, 7], 8) == mu);
kaku label: string? = mu; chant(label == mu); label = "set"; moshi (label != mu) { chant(label); }

yobu "kiso/string";
yobu "kiso/utf8";
kaku greeting = "こんにちは、Mio 🍡";
chant(greeting);
chant(string.byte_len(greeting)); chant(string.rune_count(greeting));
chant(string.contains(greeting, "Mio")); chant(string.index(greeting, "Mio"));
chant(string.has_prefix(greeting, "こん")); chant(string.has_suffix(greeting, "🍡"));
chant(string.concat("über", "straße"));
chant(string.trim_space("  空白  "));
kaku b = string.new_builder();
string.write_string(b, "α"); string.write_rune(b, 'β'); string.write_rune(b, '😀');
chant(string.builder_string(b)); chant(string.builder_len(b));
kaku bytes = string.to_bytes("é"); chant(len(bytes)); chant(bytes[0]); chant(bytes[1]);
chant(utf8.valid(bytes)); chant("tab\tquote\"backslash\\");

waza fib(n: int64) -> int64 { moshi (n < 2) { kaesu n; } kaesu fib(n - 1) + fib(n - 2); }
waza ack(m: int64, n: int64) -> int64 {
    moshi (m == 0) { kaesu n + 1; }
    moshi (n == 0) { kaesu ack(m - 1, 1); }
    kaesu ack(m - 1, ack(m, n - 1));
}
waza is_even(n: int64) -> bool { moshi (n == 0) { kaesu hai; } kaesu is_odd(n - 1); }
waza is_odd(n: int64) -> bool { moshi (n == 0) { kaesu iie; } kaesu is_even(n - 1); }
waza greet(name: string) -> unit { chant(name); }
chant(fib(20)); chant(ack(2, 3)); chant(is_even(10)); chant(is_odd(7));
greet("関数");
